/**
 * FreemindFacts — DynamoDB seeder
 *
 * Creates the FreemindFacts table (+ GSIs) if absent, then populates it with
 * facts generated by Gemini 2.0 Flash (paid tier → 2000 RPM).
 *
 * Run locally:   npx ts-node scripts/seed-facts.ts
 * Run on Lambda: deploy this file, set handler to seed-facts.handler
 *
 * Required env vars:
 *   GEMINI_API_KEY   — Google AI Studio key (paid billing account)
 *   AWS_REGION       — default: us-east-1
 *   DYNAMODB_TABLE   — default: FreemindFacts
 *   SEED_CONCURRENCY — default: 15 (safe for 2000 RPM paid tier)
 */

import dotenv from "dotenv";
dotenv.config({ path: ".env.local" });
import { createHash } from "crypto";
import {
  DynamoDBClient,
  CreateTableCommand,
  DescribeTableCommand,
  ResourceNotFoundException,
  waitUntilTableExists,
  ProjectionType,
  BillingMode,
  ScalarAttributeType,
  KeyType,
} from "@aws-sdk/client-dynamodb";
import {
  DynamoDBDocumentClient,
  QueryCommand,
  BatchWriteCommand,
  UpdateCommand,
} from "@aws-sdk/lib-dynamodb";
import { GoogleGenerativeAI } from "@google/generative-ai";

// ── Config ─────────────────────────────────────────────────────────────────────

const TABLE_NAME      = process.env.DYNAMODB_TABLE   ?? "FreemindFacts";
const REGION          = process.env.AWS_REGION        ?? "us-east-1";
const GEMINI_KEY      = process.env.GEMINI_API_KEY    ?? "";
const CONCURRENCY     = parseInt(process.env.SEED_CONCURRENCY ?? "15");
const FACTS_PER_TOPIC = 50;
const GEMINI_MODEL    = "gemini-3.1-flash-lite";

// ── AWS clients ────────────────────────────────────────────────────────────────

const ddbClient = new DynamoDBClient({ region: REGION });
const doc = DynamoDBDocumentClient.from(ddbClient, {
  marshallOptions: { removeUndefinedValues: true },
});

// ── Gemini client ──────────────────────────────────────────────────────────────

const genAI = new GoogleGenerativeAI(GEMINI_KEY);
const gemini = genAI.getGenerativeModel({ model: GEMINI_MODEL });

