// ── Utility: SHA-256 hash ──────────────────────────────────────────────────────

function sha256(text: string): string {
  return createHash("sha256").update(text, "utf8").digest("hex");
}

// ── Utility: simple semaphore for capped concurrency ──────────────────────────

class Semaphore {
  private slots: number;
  private queue: Array<() => void> = [];

  constructor(max: number) { this.slots = max; }

  acquire(): Promise<void> {
    if (this.slots > 0) { this.slots--; return Promise.resolve(); }
    return new Promise(resolve => this.queue.push(resolve));
  }

  release(): void {
    const next = this.queue.shift();
    if (next) { next(); } else { this.slots++; }
  }
}

// ── Phase 1: ensure DynamoDB table exists ──────────────────────────────────────

async function ensureTable(): Promise<void> {
  try {
    await ddbClient.send(new DescribeTableCommand({ TableName: TABLE_NAME }));
    console.log(`[seed] Table "${TABLE_NAME}" already exists — skipping creation.`);
    return;
  } catch (err) {
    if (!(err instanceof ResourceNotFoundException)) throw err;
  }

  console.log(`[seed] Creating table "${TABLE_NAME}" ...`);
  await ddbClient.send(new CreateTableCommand({
    TableName: TABLE_NAME,
    BillingMode: BillingMode.PAY_PER_REQUEST,
    AttributeDefinitions: [
      { AttributeName: "PK",          AttributeType: ScalarAttributeType.S },
      { AttributeName: "SK",          AttributeType: ScalarAttributeType.S },
      { AttributeName: "category",    AttributeType: ScalarAttributeType.S },
      { AttributeName: "shard",       AttributeType: ScalarAttributeType.N },
      { AttributeName: "contentHash", AttributeType: ScalarAttributeType.S },
      { AttributeName: "createdAt",   AttributeType: ScalarAttributeType.S },
    ],
    KeySchema: [
      { AttributeName: "PK", KeyType: KeyType.HASH  },
      { AttributeName: "SK", KeyType: KeyType.RANGE },
    ],
    GlobalSecondaryIndexes: [
      {
        IndexName:  "CategoryShardIndex",
        KeySchema: [
          { AttributeName: "category", KeyType: KeyType.HASH  },
          { AttributeName: "shard",    KeyType: KeyType.RANGE },
        ],
        Projection: { ProjectionType: ProjectionType.ALL },
      },
      {
        IndexName:  "ContentHashIndex",
        KeySchema: [
          { AttributeName: "contentHash", KeyType: KeyType.HASH  },
          { AttributeName: "createdAt",   KeyType: KeyType.RANGE },
        ],
        Projection: { ProjectionType: ProjectionType.KEYS_ONLY },
      },
    ],
  }));

  await waitUntilTableExists(
    { client: ddbClient, maxWaitTime: 120 },
    { TableName: TABLE_NAME },
  );
  console.log(`[seed] Table "${TABLE_NAME}" is ACTIVE.`);
}

// ── Phase 2: call Gemini, return raw fact strings ──────────────────────────────

async function fetchFacts(category: string, topic: string): Promise<string[]> {
  const prompt = `You are a factual knowledge database. Generate exactly ${FACTS_PER_TOPIC} unique, surprising, and educational facts about "${topic}" in the category "${category}".

Rules:
- Each fact must be a single sentence, maximum 280 characters
- Facts must be accurate, verifiable, and genuinely interesting
- No repetition between facts
- No bullet points, numbering, markdown, or any formatting
- Return ONLY a valid JSON array of strings — no text before or after
- Example format: ["Fact one.", "Fact two.", ...]`;

  const maxRetries = 4;
  let delay = 2000;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      const result = await gemini.generateContent(prompt);
      const text   = result.response.text().trim();

      // Strip markdown fences if Gemini wraps the JSON
      const clean = text
        .replace(/^```(?:json)?\s*/i, "")
        .replace(/\s*```\s*$/, "")
        .trim();

      const facts: unknown = JSON.parse(clean);

      if (
        !Array.isArray(facts) ||
        !facts.every(f => typeof f === "string" && f.length > 0)
      ) {
        throw new Error("Gemini response is not a string[]");
      }

      return (facts as string[]).filter(f => f.trim().length > 0);
    } catch (err: unknown) {
      const isRateLimit =
        String(err).includes("429") ||
        String(err).includes("RESOURCE_EXHAUSTED") ||
        String(err).includes("quota");

      if (attempt === maxRetries) {
        console.error(`[seed] Gemini failed after ${maxRetries} retries for ${category}/${topic}:`, err);
        return [];
      }

      const waitMs = isRateLimit ? delay : 1000;
      console.warn(`[seed] Gemini error (attempt ${attempt}/${maxRetries}) for ${category}/${topic} — retrying in ${waitMs}ms`);
      await new Promise(r => setTimeout(r, waitMs));
      delay = Math.min(delay * 2, 60_000);
    }
  }

  return [];
}

// ── Phase 3: dedup check via GSI-2 (ContentHashIndex) ────────────────────────
// Checks all hashes in parallel — one Query per hash, batched to 25 at a time.

async function filterDuplicates(facts: string[]): Promise<string[]> {
  const results = await Promise.all(
    facts.map(async (fact) => {
      const hash = sha256(fact.trim().toLowerCase());
      const res  = await doc.send(new QueryCommand({
        TableName:              TABLE_NAME,
        IndexName:              "ContentHashIndex",
        KeyConditionExpression: "contentHash = :h",
        ExpressionAttributeValues: { ":h": hash },
        Limit: 1,
        Select: "COUNT",
      }));
      return res.Count === 0 ? fact : null;
    }),
  );
  return results.filter((f): f is string => f !== null);
}

// ── Phase 4: DynamoDB BatchWriteItem with unprocessed-item retry ──────────────

async function batchWrite(items: Record<string, unknown>[]): Promise<void> {
  const CHUNK = 25; // DynamoDB hard limit per BatchWriteItem call
  for (let i = 0; i < items.length; i += CHUNK) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let chunk: any[] = items.slice(i, i + CHUNK).map(Item => ({ PutRequest: { Item } }));

    let attempt = 0;
    while (chunk.length > 0 && attempt < 5) {
      const res = await doc.send(new BatchWriteCommand({
        RequestItems: { [TABLE_NAME]: chunk },
      }));

      const unprocessed = res.UnprocessedItems?.[TABLE_NAME];
      if (!unprocessed || unprocessed.length === 0) break;

      // Back off before retrying unprocessed items (table throttled)
      chunk = unprocessed;
      attempt++;
      await new Promise(r => setTimeout(r, 200 * Math.pow(2, attempt)));
    }

    if (attempt === 5) {
      console.error(`[seed] BatchWrite: some items could not be written after 5 retries`);
    }
  }
}

// ── Phase 5: update META stats row ────────────────────────────────────────────

async function updateMeta(category: string, addedCount: number): Promise<void> {
  await doc.send(new UpdateCommand({
    TableName: TABLE_NAME,
    Key: { PK: `META#${category}`, SK: "STATS" },
    UpdateExpression:
      "SET lastSeeded = :ts ADD totalFacts :n",
    ExpressionAttributeValues: {
      ":ts": new Date().toISOString(),
      ":n":  addedCount,
    },
  }));
}

// ── Orchestrate one topic ──────────────────────────────────────────────────────

async function seedTopic(category: string, topic: string): Promise<number> {
  const rawFacts = await fetchFacts(category, topic);
  if (rawFacts.length === 0) return 0;

  const newFacts  = await filterDuplicates(rawFacts);
  if (newFacts.length === 0) {
    console.log(`[seed] ${category}/${topic} — all ${rawFacts.length} facts already exist`);
    return 0;
  }

  const createdAt = new Date().toISOString();
  const items = newFacts.map((fact) => {
    const factId      = crypto.randomUUID();
    const contentHash = sha256(fact.trim().toLowerCase());
    const shard       = Math.floor(Math.random() * 10); // 0-9

    return {
      PK:          `CATEGORY#${category}`,
      SK:          `FACT#${factId}`,
      factId,
      category,
      topic,
      fact,
      contentHash,
      shard,
      createdAt,
      status:  "active",
      source:  GEMINI_MODEL,
    };
  });

  await batchWrite(items);
  console.log(
    `[seed] ${category}/${topic} — wrote ${items.length} facts` +
    (rawFacts.length > newFacts.length
      ? ` (${rawFacts.length - newFacts.length} duplicates skipped)`
      : ""),
  );
  return items.length;
}

// ── Main orchestrator ──────────────────────────────────────────────────────────

interface SeedEvent {
  // Optional: seed only specific categories (useful for re-runs / repairs)
  categories?: string[];
}

export async function handler(event: SeedEvent = {}): Promise<object> {
  if (!GEMINI_KEY) throw new Error("GEMINI_API_KEY env var is not set");

  const startMs = Date.now();
  await ensureTable();

  // Build flat list of [category, topic] pairs
  const targetCategories = event.categories?.length
    ? event.categories
    : Object.keys(SEED_CATEGORIES);

  const pairs: Array<[string, string]> = targetCategories.flatMap(cat =>
    (SEED_CATEGORIES[cat] ?? []).map(topic => [cat, topic] as [string, string]),
  );

  console.log(`[seed] Starting: ${pairs.length} topics across ${targetCategories.length} categories`);
  console.log(`[seed] Concurrency: ${CONCURRENCY} parallel Gemini calls`);

  // Track per-category totals for META update
  const categoryTotals: Record<string, number> = {};
  const sem = new Semaphore(CONCURRENCY);
  let completed = 0;

  await Promise.all(
    pairs.map(async ([category, topic]) => {
      await sem.acquire();
      try {
        const added = await seedTopic(category, topic);
        categoryTotals[category] = (categoryTotals[category] ?? 0) + added;
      } finally {
        sem.release();
        completed++;
        if (completed % 25 === 0) {
          console.log(`[seed] Progress: ${completed}/${pairs.length} topics done`);
        }
      }
    }),
  );

  // Update META stats for each category
  await Promise.all(
    Object.entries(categoryTotals).map(([cat, count]) => updateMeta(cat, count)),
  );

  const totalAdded = Object.values(categoryTotals).reduce((s, n) => s + n, 0);
  const elapsed    = ((Date.now() - startMs) / 1000).toFixed(1);

  const summary = {
    ok:          true,
    topicsSeeded: pairs.length,
    factsAdded:  totalAdded,
    elapsedSec:  parseFloat(elapsed),
    breakdown:   categoryTotals,
  };

  console.log("[seed] Done:", JSON.stringify(summary, null, 2));
  return summary;
}

// ── Run directly (ts-node / node) ─────────────────────────────────────────────

const isDirectRun = process.argv[1]?.replace(/\\/g, "/").endsWith("scripts/seed-facts.ts") ||
                    process.argv[1]?.replace(/\\/g, "/").endsWith("scripts/seed-facts.js");

if (isDirectRun) {
  const categories = process.argv.slice(2); // e.g. npx tsx scripts/seed-facts.ts Mythology Science
  handler(categories.length ? { categories } : {})
    .then(() => process.exit(0))
    .catch(err => { console.error(err); process.exit(1); });
}
